+    "my_product_index"
+  ],
+  "template": {
+    "script": {
+      "lang": "mustache",
+      "source": """
+        {
+          "query": {
+            "script_score": {
+              "query": {
+                "bool": {
+                  "filter": {
+                    "range": {
+                      "{{field}}": {
+                        "{{operator}}": {{value}}
+                      }
+                    }
+                  }
+                }
+              },
+              "script": {
