+                    if (builder.humanReadable()) {
+                        builder.field("time_between_starts", TimeValue.timeValueMillis(timeBetweenStarts).toHumanReadableString(2));
+                    }
+                }
+                builder.field("data_stream_count", dataStreamStats.size());
