+                assertThat(stats.backingIndicesInError(), is(1));
+            }
+            if (stats.dataStreamName().equals("mixed")) {
+                assertThat(stats.backingIndicesInTotal(), is(1));
+                assertThat(stats.backingIndicesInError(), is(0));
+            }
